','#4C0F0F',NULL,NULL,8,NULL,NULL,'2024-12-17 01:43:28','2024-12-21 00:05:57'),(68,'Payment Mode','payment-mode','select','sandbox',NULL,'sandbox, live',10,NULL,NULL,'2024-12-17 01:43:28','2024-12-17 01:43:28'),(72,'Tax','tax','textbox',NULL,NULL,NULL,10,NULL,NULL,'2024-12-17 01:43:28','2024-12-21 00:06:01'),(91,'Puja & Prayers Link','puja-prayers-link','textbox','/puja-request',NULL,NULL,5,NULL,NULL,'2024-12-20 23:20:57','2025-02-21 06:58:12'),(92,'Puja & Prayers Link New Window','puja-prayers-link-new-window','checkbox','',NULL,NULL,5,NULL,NULL,'2024-12-20 23:20:57','2024-12-20 23:58:23'),(93,'Pledge & Support Link','pledge-support-link','textbox','/support-us',NULL,NULL,5,NULL,NULL,'2024-12-20 23:20:57','2025-02-04 12:29:01'),(94,'Pledge & Support Link New Window','pledge-support-link-new-window','checkbox','',NULL,NULL,5,NULL,NULL,'2024-12-20 23:20:57','2024-12-20 23:58:23'),(95,'Whatsapp Scan Image','whatsapp-scan-image','file','qr-code-final_m5hxlcu2f.jpg','Whatsapp Scan Image',NULL,5,NULL,NULL,'2024-12-20 23:27:33','2025-08-02 08:25:33'),(97,'Balvihar Link','balvihar-link','textbox','http://www.balviharomaha.org/',NULL,NULL,5,NULL,NULL,'2024-12-20 23:27:33','2024-12-20 23:59:40'),(98,'Balvihar Link New Window','balvihar-link-new-window','checkbox','',NULL,NULL,5,NULL,NULL,'2024-12-20 23:27:33','2024-12-20 23:58:23'),(99,'Deepam Link','deepam-link','textbox','/deepam',NULL,NULL,5,NULL,NULL,'2024-12-20 23:27:33','2025-01-04 11:23:53'),(100,'Deepam Link New Window','deepam-link-new-window','checkbox','',NULL,NULL,5,NULL,NULL,'2024-12-20 23:27:33','2024-12-20 23:58:23'),(101,'Temple Timings','temple-timings','textarea','<ul class=\"timings w-100\">\r\n  <li>\r\n    <p>Weekdays :</p>\r\n    <p>\r\n      09:00AM - 12:30PM and <br />\r\n      05:30PM - 08:30PM\r\n    </p>\r\n  </li>\r\n  <li>\r\n    <p>Weekends :</p>\r\n    <p>\r\n      09:00AM - 02:00PM and <br />\r\n      05:30PM - 08:30PM\r\n    </p>\r\n  </li>\r\n  <li>\r\n    <p>\r\n      Temple Cafeteria <br />\r\n      Saturday & Sunday :\r\n    </p>\r\n    <p>\r\n      10:30AM - 01:30PM\r\n    </p>\r\n  </li>\r\n</ul>',NULL,NULL,9,NULL,NULL,'2024-12-20 23:45:07','2025-02-18 05:20:22'),(102,'Copyright Text','copyright-text','textbox','Hindu Temple Omaha, NE, All rights reserved.',NULL,NULL,9,NULL,NULL,'2024-12-20 23:45:21','2024-12-21 00:04:13'),(103,'Currency Symbol','currency-symbol','textbox','$',NULL,NULL,10,NULL,NULL,'2025-01-31 03:28:55','2025-01-31 03:28:55'),(104,'Temple Tours Terms and Conditions','temple-tours-terms-and-conditions','heading',NULL,NULL,NULL,12,NULL,NULL,'2025-02-04 13:13:58','2025-02-04 13:13:58'),(105,'Temple Tours T&C Title','temple-tours-tc-title','textbox','I accept terms and conditions',NULL,NULL,12,NULL,NULL,'2025-02-04 13:14:32','2025-02-06 10:31:31'),(106,'Temple Tours T&C Description','temple-tours-tc-description','textarea','<h2 class=\"text-primary\">Terms & Conditions - Temple Tour</h2>\r\n<!--<p>Temple Tours.........</p>\r\n<p>No tours conducted on Saturdays and Sundays until further notice.</p>-->',NULL,NULL,12,NULL,NULL,'2025-02-04 13:15:13','2025-02-20 12:47:59'),(107,'Social Hall Booking','social-hall-booking','heading',NULL,NULL,NULL,12,NULL,NULL,'2025-02-06 09:53:00','2025-02-06 09:53:00'),(108,'Social Hall T&C Title','social-hall-tc-title','textbox','I Agree to the terms and conditions',NULL,NULL,12,NULL,NULL,'2025-02-06 09:54:16','2025-02-06 10:17:46'),(109,'Social Hall T&C Description','social-hall-tc-description','textarea','<h2 class=\"text-primary\">Terms & Conditions - Social Hall Booking</h2>\r\n\r\n<h5>The Applicant agrees to abide by the following Terms and Conditions for the use of the Social hall and other Temple facilities:</h5>\r\n\r\n<ul>\r\n  <li>Remove all boxes, decorations, flower arrangements, etc. after the event.  \r\n      Return the hall in the same condition as when rented. Clean and/or vacuum the hall, clean the tables and chairs, and stack them towards the side/back of the hall. Return all facilities in the same working condition as when rented. A part of the security deposit will be used for professional cleaning if the user does not clean the facility as required by the Temple. A Professional Cleaning Service is available with a nominal charge of $75 per event.</li>\r\n  <li>Clean and/or vacuum the hallway, coat room, etc. as well.</li>\r\n  <li>Remove any party balloons, streamers, etc. as well.</li>\r\n  <li>If the kitchen is rented, clean the kitchen stove, sink, floor, tables, utensils, etc., and return the kitchen in the same condition as when rented.</li>\r\n  <li>Remove all linens, dishes, food, and trash at the end of the event and empty them in the dumpster behind the temple.</li>\r\n  <li>Lock all Temple doors after the event is over as instructed by the Temple staff.</li>\r\n  <li>Strictly follow the capacity restrictions as ordered by the fire marshal.</li>\r\n  <li>Use the Temple Audio/Video equipment ONLY to play content appropriate to a place of worship.</li>\r\n  <li>DO NOT allow kids on the stage.</li>\r\n  <li>DO NOT tape, wire, staple, or nail anything to any wall or floor where damage can occur. Please consult the Temple staff concerning decorations.</li>\r\n  <li>DO NOT pin, tape, or hang decorations of any sort on any of the front/back/side curtains except on the ones mentioned for decoration. Please ask for details.</li>\r\n  <li>DO NOT bring pets or other animals, with the exception of seeing-eye dogs, to the Temple premises. The seeing-eye dogs are allowed only through the side door of the social hall.</li>\r\n  <li>NO HAVANS/FIRE SACRIFICE allowed in the social hall unless otherwise stated.</li>\r\n  <li>DO NOT light candles in the social hall.</li>\r\n  <li>DO NOT Photograph/Videography inside the main Temple. Photography and videography are allowed only in the social hall and outside the Temple.</li>\r\n  <li>DO NOT allow smoking, alcohol, non-vegetarian food (including but not limited to meat, poultry, egg, and fish), or anything considered unholy in the Temple premises.</li>\r\n  <li>DO NOT use Temple Audio/Video equipment (TV, sound system, etc.) to play content of adult nature, violence, crime, etc. The Temple is not responsible or liable for any inappropriate content being played on the Audio/Video equipment.</li>\r\n  <li>DO NOT allow kids to play or run around on the stage when not performing.</li>\r\n  <li>The Applicant is responsible for any accident inside the kitchen or the social hall area – the Temple is not liable for any injuries.</li>\r\n  <li>Hindu Temple is first and foremost a place of worship and education and has valuable items in its display cases. Unruly guests and unruly and unsupervised children will be asked to leave.</li>\r\n  <li>Hindu Temple will provide the venue only, and NO staff person will be present during the event. If a staff person is needed during the event, please inform us in advance.</li>\r\n  <li>Hindu Temple has tables and chairs. These are available for use at NO EXTRA charge, but a refundable deposit of $20 is required at the time of booking. The deposit will be refunded after your event, provided the tables and chairs are returned in the same condition as when rented and nicely stacked towards the side/back of the hall.</li>\r\n  <li>If the event requires the main Social hall sound system, video camera, or broadcasting facility, they are available for rent and MUST be set up/operated by the appointed Temple staff/custodian/designated volunteer ONLY. The CDs to be played during the main event can be tested on the main audio system a day or two before the event if the stage is rented for rehearsals. Rehearsals must be completed by 8:45 p.m.</li>\r\n  <li>A custodian involvement beyond temple hours involves a custodian fee of $10/hour. This includes locking up the temple after hours.</li>\r\n</ul>\r\n\r\n<h6>Security Deposit</h6>\r\n<p>Reservations are taken on a first-come, first-served basis. <b>A security deposit of $301 (for renting the main hall) and $101 (for renting the mini hall) is required to reserve your date and time.</b> This deposit does not apply towards the donation for social hall usage. It will be refunded after your event, provided there is no theft or damage to the facility and the rules of the contract were followed. We reserve the right to retain any or all of this deposit. The Security deposit will be destroyed within two weeks of the event. If the damages to the property are not sufficiently covered by the security deposit, or if the property has been misused, or if theft has been detected, the Applicant WILL be charged accordingly and future bookings might be denied.</p>\r\n\r\n<h6>Setup Fees</h6>\r\n<p>A setup fee of $25 is required for renting certain electronic items. This is NOT an optional fee and is charged only once per event, even if multiple items requiring setup fee are rented. The setup fee is waived for Gold, Platinum, and Annual packages.</p>\r\n\r\n<h6>Minimum Usage Donation</h6>\r\n<p>The minimum suggested donation for Social Hall and other Temple facilities usage is listed in the following table. The Applicant is welcome to donate more than the suggested minimum amount. All facilities are available for rent either individually or as package deals. The projector and screen are not included in any package deals, so they must be rented separately. In most cases, the Applicant might find it convenient and cheaper to rent a package.</p>\r\n<p><b>A $50 discount is available on Bronze, Silver, Gold, and Platinum packages for weekday (Mon – Thurs) usage.</b> Please check the “Reserve” column for the facilities that need to be reserved.</p>\r\n\r\n<h6>Cancellations</h6>\r\n<p>The Temple reserves the right to terminate this agreement without prior notice and without refund of the security deposit if, in its opinion, the Applicant has provided false or misleading information in the application, has defaulted in providing anything required by the application, or is in breach of any term or condition of this agreement.</p>\r\n<p>The Temple reserves the right to cancel the reservation, with at least three days of prior notice to the Applicant, when the social hall is needed for urgent temple activity as determined by the President of the Temple Executive Committee. In such cases, the Temple will refund all deposits to the Applicant in connection with such a canceled reservation.</p>\r\n<p>This agreement may be canceled by the Applicant upon giving written/email notice to the Temple at least seven days prior to the event, and in such a case, the Temple will refund all deposits less any expenses incurred on behalf of the Applicant. A $25 fee will be charged for cancellations within seven days of the event.</p>\r\n\r\n<h6>Events</h6>\r\n<p>Events have a time limit for usage, especially when another party has requested usage of the hall after the Applicant’s event. The usage time begins when the first person arrives and ends when the last service person leaves. Please account for cleanup time at the end of the event when booking the hall.</p>\r\n\r\n<h6>Payment</h6>\r\n<p>One signed copy of this agreement along with a check for the suggested donation plus deposits must be received at least ten days before the event date. The check and the signed contract can be either dropped off in the Temple “Donation Box” or mailed to the Temple. If the payment is not received by the due date, the reservation will be canceled, and a fee of $25 will be charged.</p>\r\n\r\n<h6>Changes</h6>\r\n<p>Changes to the contract are only allowed until three days prior to the event date. The first change will be free of charge, and any subsequent changes will carry a processing fee of $25.</p>\r\n\r\n<p><b>Please make checks payable to Hindu Temple Limited. There will be a charge of $20.00 for all non-sufficient fund checks.</b></p>\r\n\r\n<p><b>The Temple will not hold tentative bookings past the contract due date.</b></p>',NULL,NULL,12,NULL,NULL,'2025-02-06 09:54:39','2025-02-06 10:19:23'),(110,'Puja Request','puja-request','heading',NULL,NULL,NULL,12,NULL,NULL,'2025-02-06 10:33:11','2025-02-06 10:33:11'),(111,'Puja Request T&C Title','puja-request-tc-title','textbox','I Agree to the terms and conditions',NULL,NULL,12,NULL,NULL,'2025-02-06 10:33:45','2025-02-06 10:35:27'),(112,'Puja Request T&C Description','puja-request-tc-description','textarea','<h2 class=\"text-primary\">Terms & Conditions - Puja Request</h2>\r\n<p>Puja request terms and conditions.</p>\r\n<p>Please note that this is only a request and not confirmation . You ll get the confirmation/scheduled email separately.</p>',NULL,NULL,12,NULL,NULL,'2025-02-06 10:34:11','2025-02-06 10:35:27'),(113,'Prayer Song','prayer-song','file','Durga_407hn3dsv.mp3','Prayer Song',NULL,9,NULL,NULL,'2025-02-19 11:45:45','2025-02-19 11:49:07'),(114,'puja Request email','puja-request-email','textbox','htom.puja@gmail.com',NULL,NULL,7,NULL,NULL,'2025-06-05 06:39:54','2025-08-04 23:06:14'),(115,'socialhall booking email','socialhall-booking-email','textbox','htom.socialhall@gmail.com',NULL,NULL,7,NULL,NULL,'2025-06-05 06:40:10','2025-08-04 23:06:14'),(116,'templetour email','templetour-email','textbox','htom.tours@gmail.com',NULL,NULL,7,NULL,NULL,'2025-06-05 06:40:31','2025-08-07 01:23:51'),(117,'Home Events','home-events','textarea','<div style=\"font-family: Arial, Helvetica, sans-serif;\">\r\n<div style=\"font-size:24px; font-weight:bold; margin-bottom:10px;\">Weekly Updates</div>\r\n\r\n<div style=\"font-size:15px; font-weight:bold; margin-top:15px; margin-bottom:5px;\">Morning Puja Schedule</div>\r\n<table style=\"width:100%; border-collapse:collapse; font-size:12px; margin-bottom:15px;\" border=\"1\" cellpadding=\"5\" cellspacing=\"0\">\r\n  <tr style=\"background-color:#f2f2f2;\">\r\n    <th align=\"center\">Day</th>\r\n    <th  align=\"center\">Priests</th>\r\n    <th  align=\"left\">Puja</th>\r\n    <th  align=\"center\">Time</th>\r\n  </tr>\r\n  <tr><td  align=\"center\">Monday</td><td  align=\"center\">3 Priests</td><td  align=\"left\">Ganesha Abhishekam</td><td  align=\"center\">10:00 AM</td></tr>\r\n  <tr><td align=\"center\">Tuesday</td><td align=\"center\">3 Priests</td><td align=\"left\">Ganesha Abhishekam</td><td align=\"center\">10:00 AM</td></tr>\r\n  <tr><td align=\"center\">Wednesday</td><td align=\"center\">2 Priests</td><td align=\"left\">Ganesha Abhishekam</td><td align=\"center\">10:00 AM</td></tr>\r\n  <tr><td align=\"center\">Thursday</td><td align=\"center\">2 Priests</td><td align=\"left\">Ganesha Abhishekam</td><td align=\"center\">10:00 AM</td></tr>\r\n  <tr><td align=\"center\">Friday</td><td align=\"center\">3 Priests</td><td align=\"left\">Ganesha Abhishekam</td><td align=\"center\">10:00 AM</td></tr>\r\n  <tr><td align=\"center\">Saturday</td><td align=\"center\">-</td><td align=\"left\">Sri Balaji Abhishekam</td><td align=\"center\">10:00 AM</td></tr>\r\n  <tr>\r\n    <td align=\"center\">Sunday</td>\r\n    <td align=\"center\">-</td>\r\n    <td align=\"left\">\r\n      Ganesha Abhishekam<br>\r\n      Jagannatha Swamy Puja\r\n    </td>\r\n    <td align=\"center\">\r\n      10:00 AM<br>\r\n      10:00 AM\r\n    </td>\r\n  </tr>\r\n</table>\r\n\r\n<div style=\"font-size:15px; font-weight:bold; margin-top:15px; margin-bottom:5px;\">Evening Puja Schedule</div>\r\n<table style=\"width:100%; border-collapse:collapse; font-size:12px; margin-bottom:15px;\" border=\"1\" cellpadding=\"5\" cellspacing=\"0\">\r\n  <tr style=\"background-color:#f2f2f2;\">\r\n    <th align=\"center\">Day</th>\r\n    <th align=\"left\">Puja</th>\r\n    <th align=\"center\">Time</th>\r\n  </tr>\r\n  <tr><td align=\"center\">Monday</td><td align=\"left\">Shiva Abhishekam</td><td align=\"center\"> 06:30 PM</td></tr>\r\n  <tr>\r\n    <td align=\"center\">Tuesday</td>\r\n    <td align=\"left\">\r\n      Sri Subramanya Swamy Abhishekam<br>\r\n      Hanuman Puja<br>\r\n      Sri Ram Privara Puja\r\n    </td>\r\n    <td align=\"center\">06:30 PM</td>\r\n  </tr>\r\n  <tr><td align=\"center\">Wednesday</td><td align=\"left\">Radha Krishna Puja</td><td align=\"center\">06:30 PM</td></tr>\r\n  <tr><td align=\"center\">Thursday</td><td align=\"left\">Sai Baba Abhishekam</td><td align=\"center\">06:30 PM</td></tr>\r\n  <tr><td align=\"center\">Friday</td><td align=\"left\">Devi Abhishekam</td><td align=\"center\">06:30 PM</td></tr>\r\n  <tr><td align=\"center\">Saturday</td><td align=\"left\">Ayyappa Abhishekam</td><td align=\"center\">06:30 PM</td></tr>\r\n</table>\r\n\r\n<div style=\"font-size:15px; font-weight:bold; margin-top:15px; margin-bottom:5px;\">Special Pujas</div>\r\n<table style=\"width:100%; border-collapse:collapse; font-size:12px;\" border=\"1\" cellpadding=\"5\" cellspacing=\"0\">\r\n  <tr style=\"background-color:#f2f2f2;\">\r\n    <th align=\"left\">Occasion</th>\r\n    <th align=\"left\">Puja</th>\r\n    <th align=\"center\">Time</th>\r\n  </tr>\r\n  <tr><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Every Month First Saturday</td><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Navagraha Abhishekam</td><td align=\"center\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">10:00 AM</td></tr>\r\n  <tr><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">All Days</td><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Sai Baba Aarathi</td><td align=\"center\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">06:30 PM</td></tr>\r\n  <tr><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Pournami Days (Weekdays)</td><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\"  >Community Sri Satyanarayana Swamy Vratam</td><td align=\"center\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\" >06:30 PM</td></tr>\r\n  <tr><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Pournami Days (Weekends)</td><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Community Sri Satyanarayana Swamy Vratam</td><td align=\"center\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">10:30 AM</td></tr>\r\n  <tr><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Monthly Once</td><td align=\"left\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">Sankata Hara Chaturthi Puja</td><td align=\"center\" style=\"font-weight:bold; font-family: Arial, Helvetica, sans-serif;\">06:30 PM</td></tr>\r\n</table>\r\n</div>',NULL,NULL,5,NULL,NULL,'2025-08-11 03:55:09','2025-08-12 01:05:12'),(118,'Home Events Button','home-events-button','textbox','Weekly Updates',NULL,NULL,5,NULL,NULL,'2025-08-11 04:48:06','2025-08-11 04:51:17');
/*!40000 ALTER TABLE `application_settings` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `blog_categories`
--

DROP TABLE IF EXISTS `blog_categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blog_categories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
