INSERT INTO `events` VALUES (5,1,'Community Sri SatyaNarayana Swamy Vratam','community-sri-satyanarayana-swamy-vratam','SatyanarayanaJune2025_tvld5qojn.jpg',NULL,'2024-12-14 11:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-02-01 09:59:48','2025-06-04 10:38:02'),(6,1,'Monthly Sankashti (Sankatahara Chathurthi Pooja)','monthly-sankashti-sankatahara-chathurthi-pooja','SankataharaJune2025_jujx9prya.jpg',NULL,'2025-07-31 21:19:00','2025-07-31 21:20:00',NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-06-04 09:52:45','2025-07-25 21:20:15'),(7,1,'Brahmothsava 2025','brahmothsava-2025','Brahmotsavam_2025_gug7c7w6l.jpg',NULL,'2025-06-07 09:30:00','2025-06-08 12:00:00','<div style=\"text-align: center;\"><span style=\"color: #e03e2d;\"><strong>Program Details</strong></span></div>\r\n<div style=\"text-align: center;\">June 7th Saturday &ndash; Morning</div>\r\n<div style=\"text-align: center;\">09:30 AM - 10:00 AM Ganesha Puja and Sankalpam</div>\r\n<div style=\"text-align: center;\">10:00 AM &ndash; 01:00 PM Prasanna Ganapati Havan, Parivara Devata Havan</div>\r\n<div style=\"text-align: center;\">Sudarshana Homam</div>\r\n<div style=\"text-align: center;\">Purnahuti Havan By Our Temple Founders</div>\r\n<div style=\"text-align: center;\">Maha Purnahuti by Priests</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">June 8th Sunday &ndash; Morning</div>\r\n<div style=\"text-align: center;\">09:00 AM - 09:30 AM Nitya Aradhana</div>\r\n<div style=\"text-align: center;\">09:30 AM - 11:00 AM Ganapathi Abhisekham</div>\r\n<div style=\"text-align: center;\">10:00 AM- 11:00 AM Jagannatha Puja</div>\r\n<div style=\"text-align: center;\">Rathotsvam followed by Mangala Arathi.</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\"><span style=\"color: #e03e2d;\"><strong>Program Sponsors</strong></span></div>\r\n<div style=\"text-align: center;\">Event Sponsorship $101.00</div>\r\n<div style=\"text-align: center;\">Abhiseka Sponsorship $41.00</div>\r\n<p style=\"text-align: center;\">&nbsp;</p>',NULL,NULL,NULL,NULL,NULL,0,1,'2025-06-07 00:30:22','2025-06-07 00:30:22'),(8,1,'Snana Purnima','snana-purnima','SnanaPurnima_2025_a5ff8rjve.jpg',NULL,'2025-06-10 18:00:00','2025-06-10 20:00:00','<div style=\"text-align: center;\"><span style=\"color: #e03e2d;\"><strong>Program Details</strong></span></div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">Snana Yatra, a Bathing ceremony of Lord Jagannath, Lord Balabhadra, Devi Subhadra, and the Sudarshana Chakra.&nbsp; The bathing ritual symbolizes purification and rejuvenation, aligning with seasonal transitions.</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>\r\n<div style=\"text-align: center;\">On the day of the snan Poornima ceremony, the deities of Lord Jagannath, Lord Balabhadra and Devi Subhadra are escorted out of the Ratnasimhasan from the sanctum to the Snan Bedi amidst chanting of mantras and to the sounds of drums, cymbals, bugles and bhantas. This is known as the Pahandi Procession.</div>\r\n<p style=\"text-align: center;\">&nbsp;</p>',NULL,NULL,NULL,NULL,NULL,0,1,'2025-06-07 00:32:55','2025-06-07 00:32:55'),(9,1,'Monthly Sankasthi','monthly-sankasthi','unnamed_i82a9ln7z.jpg',NULL,'2025-07-13 21:11:00','2025-07-31 21:11:00',NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-07-25 21:18:53','2025-07-25 21:18:53'),(10,1,'Yajur Upakarma','yajur-upakarma','8th_gm7miq8gi.jpg',NULL,'2025-08-08 06:30:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:16:22','2025-08-07 16:29:44'),(11,1,'Community Sri Satyanarayana Swamy Vratam','community-sri-satyanarayana-swamy-vratam','8th-(2)_qpvatcfzp.jpg',NULL,'2025-08-08 18:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:23:17','2025-08-07 16:30:51'),(12,1,'Monthly Sankasthi','monthly-sankasthi','12th_m6qb5shhy.jpg',NULL,'2025-08-12 18:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:29:36','2025-08-07 16:31:42'),(13,1,'Janmasthami Celebration','janmasthami-celebration','15th_akuox3w6a.jpg',NULL,'2025-08-15 18:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:31:19','2025-08-07 16:40:16'),(14,1,'Ganesh Chathurtri Pooja','ganesh-chathurtri-pooja','26th_r4alkhcm5.jpg',NULL,'2025-08-25 23:30:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:37:20','2025-08-02 13:31:40'),(15,1,'Rishi Panchami','rishi-panchami','27th_2wpm3avci.jpg',NULL,'2025-08-27 10:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:39:18','2025-08-07 16:41:12'),(16,1,'Ganesha Chaturthi Celebrations','ganesha-chaturthi-celebrations','Chaturthi_dqol7ng1c.jpg',NULL,'2025-08-29 10:00:00','2025-08-31 23:59:00',NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-02 12:41:05','2025-08-07 16:25:56'),(17,1,'Sri Vara Mahalakshmi Puja','sri-vara-mahalakshmi-puja','unnamed-(2)_i1qnu5yjc.jpg',NULL,'2025-08-08 09:30:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,'2025-08-06 21:54:27','2025-08-07 16:30:08'),(18,1,'Kuzhandhai Velan Kavadi','kuzhandhai-velan-kavadi','IMG_5403_ftc4bn71y.jpg','Kuzhandhai Velan Kavadi','2025-08-22 07:00:00','2025-08-23 20:45:00','<p>Hindu Temple, Omaha cordially invites you and your famlily for Murugan festival <strong>\"Kuzhandhai Velan Kavadi\"</strong></p>',NULL,NULL,'Hindu Temple Kuzhandhai Velan Kavadi','Hindu, Temple, Hindu Temple, Kuzhandhai Velan Kavadi','Hindu Temple Kuzhandhai Velan Kavadi',0,1,'2025-08-06 23:40:48','2025-08-12 23:43:25');
