--
-- Table structure for table `tbl_order_hall_booking`
--

DROP TABLE IF EXISTS `tbl_order_hall_booking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_order_hall_booking` (
  `order_id` int unsigned NOT NULL,
  `order_no` varchar(10) NOT NULL,
  `order_date` date NOT NULL,
  `order_status` varchar(20) NOT NULL,
  `payment_status` varchar(10) NOT NULL DEFAULT 'PENDING',
  `hall_request_id` varchar(50) NOT NULL,
  `currency` varchar(10) NOT NULL,
  `total_amount` float(8,2) NOT NULL,
  `type_of_event` varchar(20) NOT NULL,
  `first_name` varchar(255) NOT NULL,
  `last_name` varchar(255) DEFAULT NULL,
  `address` varchar(1000) DEFAULT NULL,
  `country_id` int DEFAULT '0',
  `country_name` varchar(255) DEFAULT NULL,
  `state_id` int DEFAULT '0',
  `state_name` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `pincode` varchar(6) DEFAULT NULL,
  `primary_phone` varchar(50) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `event_type_id` int DEFAULT '0',
  `event_type_name` varchar(255) DEFAULT NULL,
  `other_event_type` varchar(255) DEFAULT NULL,
  `date_of_event` date NOT NULL DEFAULT '0000-00-00',
  `alternate_date_of_event` date DEFAULT '0000-00-00',
  `start_time` time DEFAULT '00:00:00',
  `hours_duration` int DEFAULT '0',
  `comment` text,
  `accept_terms` tinyint(1) DEFAULT '0',
  `status` varchar(10) NOT NULL DEFAULT 'ACTIVE',
  `name_of_requestor` varchar(255) DEFAULT NULL,
  `ref_order_id` int DEFAULT '0',
  `cancelled_by_name_of_requestor` varchar(255) DEFAULT NULL,
  `cancelled_by` varchar(255) DEFAULT NULL,
  `cancel_comment` text,
  `cancel_date` datetime DEFAULT NULL,
  `confirmed_date_of_event` date DEFAULT NULL,
  `confirmed_time` time DEFAULT NULL,
  `admin_comments` text,
  `admin_cancel_comments` text,
  `cancel_cc_email` varchar(255) DEFAULT NULL,
  `confirmed_cc_email` varchar(255) DEFAULT NULL,
  `confirmed_by` varchar(100) DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `main_status` varchar(20) DEFAULT '',
  `add_ip` varchar(20) NOT NULL,
  `add_time` datetime NOT NULL,
  `add_by` varchar(50) NOT NULL,
  `update_ip` varchar(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `update_by` varchar(50) DEFAULT NULL,
  `payment_gateway` varchar(100) DEFAULT '',
  PRIMARY KEY (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

