DROP TABLE IF EXISTS `tbl_temple_tours`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_temple_tours` (
  `tour_id` int unsigned NOT NULL,
  `tour_request_id` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `tour_date` date NOT NULL,
  `tour_time` time NOT NULL,
  `alternate_tour_date` date DEFAULT NULL,
  `alternate_tour_time` time DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `primary_phone` varchar(50) NOT NULL,
  `total_visitor` int DEFAULT '0',
  `age_range_of_group` varchar(255) DEFAULT NULL,
  `ck_last_visit` tinyint(1) DEFAULT NULL,
  `last_visit_to_temple` varchar(255) DEFAULT NULL,
  `comment` text,
  `accept_terms` tinyint(1) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'ACTIVE',
  `ref_tour_id` int DEFAULT '0',
  `confirmed_tour_date` date DEFAULT NULL,
  `confirmed_tour_time` time DEFAULT NULL,
  `confirmed_tour_guide` varchar(255) DEFAULT '',
  `admin_comments` text,
  `confirmed_cc_email` varchar(255) DEFAULT '',
  `confirmed_by` varchar(255) DEFAULT '',
  `confirmed_at` datetime DEFAULT NULL,
  `tour_status` varchar(20) NOT NULL,
  `add_ip` varchar(20) NOT NULL,
  `add_time` datetime NOT NULL,
  `add_by` varchar(50) DEFAULT NULL,
  `update_ip` varchar(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `update_by` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`tour_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

